Given two m x n matrices m1 and m2, the task is to subtract m2 from m1 and return res.Input: m1 = {{1, 2},                     {3, 4}},          m2 = {{4, 3},                     {2, 1}}Output: {{-3,  -1},                  {1,  3}}Input: m1 = {{3, 3, 3},                     {3, 3, 3}},           m1 = {{2, 2, 2},                     {1, 1, 1}},Output:  {{1, 1, 1},                {2, 2, 2}},We traverse both matrices element by element and subtract m2[i][j] from m1[i][j].
            C++

    #include <iostream>
#include <vector>
using namespace std;

// This function subtracts m2 from m1 and
// stores the result in res
void subtract(vector<vector<int>>& m1, 
              vector<vector<int>>& m2, 
              vector<vector<int>>& res) 
{
    int rows = m1.size();
    int cols = m1[0].size();

    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            res[i][j] = m1[i][j] - m2[i][j];
}

// Driver code
int main() 
{
    // Define two rectangular matrices
    vector<vector<int>> m1 = { {1, 2, 3}, 
                                {4, 5, 6} };
    vector<vector<int>> m2 = { {1, 1, 1}, 
                                {1, 1, 1} };

    // Result matrix with the same dimensions
    vector<vector<int>> res(m1.size(), vector<int>(m1[0].size()));

    // Perform the subtraction
    subtract(m1, m2, res);

    // Print the result matrix
    cout << "Result matrix is:" << endl;
    for (auto& row : res) 
    {
        for (int val : row) 
            cout << val << " ";
        cout << endl;
    }

    return 0;
}


