def subtract(m1, m2):
    rows = len(m1)
    cols = len(m1[0])
    res = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            res[i][j] = m1[i][j] - m2[i][j]
    return res

