function subtract($m1, $m2) {
    $rows = count($m1);
    $cols = count($m1[0]);
    $res = array();

    for ($i = 0; $i < $rows; $i++) {
        for ($j = 0; $j < $cols; $j++) {
            $res[$i][$j] = $m1[$i][$j] - $m2[$i][$j];
        }
    }
    return $res;
}

